mongodb:createCollection.mongodb:options:
{
    validator: {
        $jsonSchema: {
            bsonType: 'object',
            properties: {
                _id: {
                    bsonType: 'long',
                    description: 'Id must be long type and required'
                },
                passengerScore: {
                    bsonType: 'int',
                    minimum: 1,
                    maximum: 5,
                    description: 'passengerScore must be an integer in [ 1, 5 ]'
                },
                passengerComment: {
                    bsonType: 'string',
                    description: 'passengerComment must be a string'
                },
                driverScore: {
                    bsonType: 'int',
                    minimum: 1,
                    maximum: 5,
                    description: 'driverScore must be an integer in [ 1, 5 ]'
                },
                driverComment: {
                    bsonType: 'string',
                    description: 'driverComment must be a string'
                }
            },
            allOf: [
                {
                    oneOf: [
                        {
                            not: {
                                required: [
                                    'passengerComment'
                                ]
                            }
                        },
                        {
                            required: [
                                'passengerScore',
                                'passengerComment'
                            ]
                        }
                    ]
                },
                {
                    oneOf: [
                        {
                            not: {
                                required: [
                                    'driverComment'
                                ]
                            }
                        },
                        {
                            required: [
                                'driverScore',
                                'driverComment'
                            ]
                        }
                    ]
                }
            ]
        }
    },
    validationLevel: "strict",
    validationAction: "error"
}
